67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    /**
73	     * Dedicated audit logger. On a successful owner create an audit line is emitted here carrying the
74	     * new owner's id, its assigned {@code customerCode}, its {@code registrationDate} and its
75	     * numeric {@code membershipLevel}.
76	     */
77	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
78	
79	    /**
80	     * Monotonically increasing sequence assigned to each structured {@code OWNER_CREATED} audit event,
81	     * so the immutable event stream carries a strictly increasing {@code seq} across creates.
82	     */
83	    private static final java.util.concurrent.atomic.AtomicLong AUDIT_EVENT_SEQ =
84	        new java.util.concurrent.atomic.AtomicLong();
85	
86	    /**
87	     * Name of the optional request header carrying an idempotency token for owner creation.
88	     */
89	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
90	
91	    /**
92	     * Idempotency store mapping a previously seen {@code Idempotency-Key} to the id of the owner
93	     * originally created under it. When a create repeats with a key already present here, the
94	     * originally created owner is returned (200 OK) instead of creating a duplicate.
95	     */
96	    private final java.util.Map<String, Integer> idempotencyKeyToOwnerId =
97	        new java.util.concurrent.ConcurrentHashMap<>();
98	
99	    private final ClinicService clinicService;
100	
101	    private final OwnerMapper ownerMapper;
102	
103	    private final PetMapper petMapper;
104	
105	    private final VisitMapper visitMapper;
106	
107	    public OwnerRestControllerV1(ClinicService clinicService,
108	                                 OwnerMapper ownerMapper,
109	                                 PetMapper petMapper,
110	                                 VisitMapper visitMapper) {
111	        this.clinicService = clinicService;
112	        this.ownerMapper = ownerMapper;
113	        this.petMapper = petMapper;
114	        this.visitMapper = visitMapper;
115	    }
