142	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
143	    @Override
144	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
145	        String idempotencyKey = currentIdempotencyKey();
146	        if (idempotencyKey != null) {
147	            Integer existingId = idempotencyKeyToOwnerId.get(idempotencyKey);
148	            if (existingId != null) {
149	                Owner existing = this.clinicService.findOwnerById(existingId);
150	                if (existing != null) {
151	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
152	                }
153	            }
154	        }
155	        HttpHeaders headers = new HttpHeaders();
156	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
157	        applyAddress(owner, ownerFieldsDto);
158	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
159	        rejectFutureRegistrationDate(registrationDate);
160	        if (registrationDate == null) {
161	            registrationDate = java.time.LocalDate.now();
162	        }
163	        registrationDate = toBusinessDay(registrationDate);
164	        owner.setRegistrationDate(registrationDate);
165	        rejectDailyLimitReached(registrationDate);
166	        rejectCityAtCapacity(owner.getCity());
167	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
168	        owner.setTelephone(telephone);
169	        String email = normalizeEmail(ownerFieldsDto.getEmail());
170	        owner.setEmail(email);
171	        owner.setPostcode(validatePostcode(owner.getCity(), ownerFieldsDto.getPostcode()));
172	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
173	        rejectDuplicateIdentity(owner);
174	        // Joining an existing household is now permitted (an exact-identity duplicate is still
175	        // rejected above); a joiner's membershipLevel is instead capped one above the household's
176	        // current maximum (see cappedMembershipLevel).
177	        String region = Localities.region(owner.getPostcode(), owner.getCity());
178	        owner.setCustomerCode(assignCustomerCode(region, owner.getTelephone(), owner.getLastName()));
179	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
180	        owner.setBulkSignupWarning(computeBulkSignupWarning(registrationDate));
181	        owner.setHouseholdSize(countHouseholdMembers(owner.getLastName(), owner.getPostcode()) + 1);
182	        owner.setMembershipLevel(cappedMembershipLevel(owner));
183	        // A declared household member (sharesHousehold) is created but is not a suspected duplicate.
184	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicateOf(owner);
185	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
186	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
187	        this.clinicService.saveOwner(owner);
188	        if (idempotencyKey != null) {
189	            idempotencyKeyToOwnerId.put(idempotencyKey, owner.getId());
190	        }
191	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
192	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
193	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
194	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
195	        AUDIT.info(ownerCreatedEvent(owner, ownerDto));
196	        headers.setLocation(UriComponentsBuilder.newInstance()
197	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
198	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
199	    }
200	
201	    /**
202	     * Builds the immutable structured {@code OWNER_CREATED} audit event emitted (in addition to the
203	     * human-readable audit line) on a successful create, as a JSON object
204	     * {@code {seq, ownerId, customerCode, membershipLevel, event:'OWNER_CREATED'}}. The {@code seq} is
205	     * a fresh value from the monotonically increasing {@link #AUDIT_EVENT_SEQ} sequence, so the event
206	     * stream is strictly ordered across creates.
207	     * <p>
208	     * The {@code customerCode} field carries the owner's current primary identifier (see
209	     * {@link #primaryIdentifier}); it is the {@code customerCode} today and becomes whatever replaces it
210	     * once the identifier is unified, so the event always names the owner by its live primary identifier.
211	     *
212	     * @param owner the just-saved owner
213	     * @param ownerDto the mapped DTO, used for the (possibly derived) {@code membershipLevel}
214	     * @return the JSON-encoded structured event
215	     */
216	    private String ownerCreatedEvent(Owner owner, OwnerDto ownerDto) {
217	        StringBuilder json = new StringBuilder(128);
218	        json.append('{');
219	        json.append("\"seq\":").append(AUDIT_EVENT_SEQ.incrementAndGet());
220	        json.append(",\"ownerId\":").append(owner.getId());
221	        json.append(",\"customerCode\":").append(jsonString(primaryIdentifier(owner)));
222	        json.append(",\"membershipLevel\":").append(ownerDto.getMembershipLevel());
223	        json.append(",\"event\":\"OWNER_CREATED\"");
224	        json.append('}');
225	        return json.toString();
226	    }
227	
228	    /**
229	     * The owner's current primary identifier carried by the structured audit event. Today this is the
230	     * assigned {@code customerCode}; when the identifier is later unified into the {@code memberId} this
231	     * is the sole place to switch, so the event begins carrying the {@code memberId} instead.
232	     *
233	     * @param owner the just-saved owner
234	     * @return the owner's live primary identifier
235	     */
236	    private String primaryIdentifier(Owner owner) {
237	        return owner.getCustomerCode();
238	    }
239	
240	    /**
241	     * Encodes a value as a JSON string literal (quoted, with the JSON-significant characters escaped),
242	     * or the literal {@code null} when the value is absent.
243	     */
244	    private static String jsonString(String value) {
245	        if (value == null) {
246	            return "null";
247	        }
248	        StringBuilder sb = new StringBuilder(value.length() + 2);
249	        sb.append('"');
250	        for (int i = 0; i < value.length(); i++) {
251	            char c = value.charAt(i);
252	            switch (c) {
253	                case '"' -> sb.append("\\\"");
254	                case '\\' -> sb.append("\\\\");
255	                case '\n' -> sb.append("\\n");
256	                case '\r' -> sb.append("\\r");
257	                case '\t' -> sb.append("\\t");
258	                default -> {
259	                    if (c < 0x20) {
260	                        sb.append(String.format("\\u%04x", (int) c));
261	                    } else {
262	                        sb.append(c);
263	                    }
264	                }
265	            }
266	        }
267	        sb.append('"');
268	        return sb.toString();
269	    }
270	
271	    /**
272	     * Reads the optional {@code Idempotency-Key} header from the current request, if any. A create
273	     * carrying this header is idempotent: the first create under a key is recorded, and a later create
274	     * with the same key returns the originally created owner instead of creating a duplicate.
275	     *
276	     * @return the trimmed idempotency key, or {@code null} when the header is absent, blank or there is
277	     *         no active servlet request
278	     */
279	    private String currentIdempotencyKey() {
280	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
281	        if (attributes instanceof ServletRequestAttributes servletAttributes) {
282	            String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
283	            if (key != null && !key.isBlank()) {
284	                return key.trim();
285	            }
286	        }
287	        return null;
288	    }
289	
290	    /**
291	     * Rejects creating an owner whose supplied {@code registrationDate} is later than the server
292	     * date (in the future). Only an explicitly supplied date is validated; a {@code null} date
293	     * (which later defaults to the server date) is accepted. The check is against the raw supplied
294	     * date, before any business-day adjustment.
295	     *
296	     * @param registrationDate the supplied registration date, or {@code null} when none was supplied
297	     * @throws FutureRegistrationDateException (400 Bad Request) if the supplied date is in the future
298	     */
299	    private void rejectFutureRegistrationDate(java.time.LocalDate registrationDate) {
300	        if (registrationDate != null && registrationDate.isAfter(java.time.LocalDate.now())) {
301	            throw new FutureRegistrationDateException(registrationDate);
302	        }
303	    }
304	
305	    /**
306	     * The maximum number of owners that may be created in a single day. Creating an owner once this
307	     * many owners already carry today's {@code registrationDate} is rejected.
308	     */
309	    private static final int DAILY_OWNER_LIMIT = 100;
310	
311	    /**
312	     * Rejects creating an owner once {@value #DAILY_OWNER_LIMIT} or more owners already carry the
313	     * given business day as their {@code registrationDate}. The count is keyed by the
314	     * business-day-adjusted registration date of the owner being created (see
315	     * {@link #toBusinessDay}), so all owners falling on the same business day count together. Owners
316	     * with no {@code registrationDate} are ignored.
317	     *
318	     * @param registrationDate the business-day-adjusted registration date of the owner being created
319	     * @throws DailyOwnerLimitException (429 Too Many Requests) if the daily limit is already reached
320	     */
321	    private void rejectDailyLimitReached(java.time.LocalDate registrationDate) {
322	        long count = this.clinicService.findAllOwners().stream()
323	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
324	            .count();
325	        if (count >= DAILY_OWNER_LIMIT) {
326	            throw new DailyOwnerLimitException(registrationDate);
327	        }
328	    }
329	
330	    /**
331	     * The threshold of owners already created on a business day beyond which a bulk-signup warning is
332	     * raised on a new owner. Once strictly more than this many owners already carry the day as their
333	     * {@code registrationDate}, the new owner's {@code bulkSignupWarning} is set to {@code true}.
334	     */
335	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
336	
337	    /**
338	     * Computes the {@code bulkSignupWarning} for an owner being created: {@code true} when more than
339	     * {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created today, otherwise
340	     * {@code false}. Existing owners are counted the same way the daily-limit rule counts them (see
341	     * {@link #rejectDailyLimitReached}), keyed by the business-day-adjusted registration date, and the
342	     * owner being created is excluded (it has not yet been saved).
343	     *
344	     * @param registrationDate the business-day-adjusted registration date of the owner being created
345	     * @return {@code true} if more than the threshold of owners already carry this business day
346	     */
347	    private boolean computeBulkSignupWarning(java.time.LocalDate registrationDate) {
348	        long count = this.clinicService.findAllOwners().stream()
349	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
350	            .count();
351	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
352	    }
353	
354	    /**
355	     * The fixed public holidays the business-day roll skips. A registration date landing on any of
356	     * these dates is rolled forward, just as it is for a weekend.
357	     */
358	    private static final java.util.Set<java.time.LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
359	        java.time.LocalDate.parse("2026-01-01"),
360	        java.time.LocalDate.parse("2026-01-26"),
361	        java.time.LocalDate.parse("2026-04-25"),
362	        java.time.LocalDate.parse("2026-12-25"),
363	        java.time.LocalDate.parse("2026-12-28"));
364	
365	    /**
366	     * Rolls a registration date forward onto a business day: a Saturday, Sunday or listed public
367	     * holiday is moved forward to the next non-holiday weekday; an ordinary weekday is returned
368	     * unchanged. This applies to the effective registration date whether it was supplied in the
369	     * request or defaulted to the server date, and every value derived from the registration date
370	     * uses the adjusted result.
371	     *
372	     * @param date the effective registration date
373	     * @return {@code date} itself when it is a non-holiday weekday, otherwise the next business day
374	     */
375	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
376	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
377	            || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
378	            || PUBLIC_HOLIDAYS.contains(date)) {
379	            date = date.plusDays(1);
380	        }
381	        return date;
382	    }
383	
384	    /**
385	     * The maximum number of owners a single city may contain. Creating an owner in a city that
386	     * already holds this many owners is rejected.
387	     */
388	    private static final int CITY_CAPACITY = 50;
389	
390	    /**
391	     * Rejects creating an owner whose city already contains {@value #CITY_CAPACITY} or more owners.
392	     * Owners are counted per city comparing the city name case-insensitively (a {@code null} city is
393	     * treated as empty).
394	     *
395	     * @param city the city of the owner being created
396	     * @throws CityAtCapacityException (409 Conflict) if the city is already at capacity
397	     */
398	    private void rejectCityAtCapacity(String city) {
399	        String cityValue = city == null ? "" : city;
400	        long count = this.clinicService.findAllOwners().stream()
401	            .filter(existing -> cityValue.equalsIgnoreCase(
402	                existing.getCity() == null ? "" : existing.getCity()))
403	            .count();
404	        if (count >= CITY_CAPACITY) {
405	            throw new CityAtCapacityException(city);
406	        }
407	    }
408	
409	    /**
410	     * Assigns an owner's {@code customerCode} on create, formatted {@code '<REGION>-<HASH8>'} where
411	     * REGION is the owner's canonical region (derived by preferring the postcode, see
412	     * {@link Localities#region(String, String)} — the same region derivation shared with the
413	     * {@code locality}) and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest of
414	     * the normalized (E.164) telephone concatenated with the last name (e.g. {@code 'NSW-3A7F9C2E'}).
415	     * The code is derived from the owner's own identity fields; it carries no sequence number.
416	     * <p>
417	     * When the computed code collides with an existing owner's {@code customerCode}, it is
418	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes
419	     * it unique (e.g. {@code 'NSW-3A7F9C2E-2'}), and the de-duplicated code is returned.
420	     *
421	     * @param region the owner's canonical region (the identity's REGION, shared with the locality)
422	     * @param telephone the owner's normalized (E.164) telephone
423	     * @param lastName the owner's last name
424	     * @return the assigned customer code, de-duplicated to be unique among existing owners
425	     */
426	    private String assignCustomerCode(String region, String telephone, String lastName) {
427	        String basis = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
428	        String hash8 = sha256UpperHex(basis).substring(0, 8);
429	        String code = region + "-" + hash8;
430	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
431	            .map(Owner::getCustomerCode)
432	            .filter(java.util.Objects::nonNull)
433	            .collect(java.util.stream.Collectors.toSet());
434	        if (!existing.contains(code)) {
435	            return code;
436	        }
437	        for (int n = 2; ; n++) {
438	            String candidate = code + "-" + n;
439	            if (!existing.contains(candidate)) {
440	                return candidate;
441	            }
442	        }
443	    }
444	
445	    /**
446	     * Returns the full upper-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
447	     */
448	    private static String sha256UpperHex(String value) {
449	        try {
450	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
451	                .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
452	            StringBuilder sb = new StringBuilder(digest.length * 2);
453	            for (byte b : digest) {
454	                sb.append(String.format("%02X", b));
455	            }
456	            return sb.toString();
457	        }
458	        catch (java.security.NoSuchAlgorithmException e) {
459	            throw new IllegalStateException("SHA-256 not available", e);
460	        }
461	    }
462	
463	    /**
464	     * Counts how many existing owners share the given first and last name, compared
465	     * case-insensitively, at the time this owner is created. The value excludes the owner
466	     * being created (which has not yet been saved) and is stored on the new owner and returned
467	     * as its {@code namesakeCount}.
468	     *
469	     * @param firstName the first name of the owner being created
470	     * @param lastName the last name of the owner being created
471	     * @return the number of existing owners with the same first and last name
472	     */
473	    private int countNamesakes(String firstName, String lastName) {
474	        String first = firstName == null ? "" : firstName;
475	        String last = lastName == null ? "" : lastName;
476	        return (int) this.clinicService.findAllOwners().stream()
477	            .filter(existing -> first.equalsIgnoreCase(existing.getFirstName())
478	                && last.equalsIgnoreCase(existing.getLastName()))
479	            .count();
480	    }
481	
482	    /**
483	     * Counts how many existing owners belong to the same household as the owner being created, i.e.
484	     * share its {@code householdId} (derived by {@link Households#householdId} from the normalized last
485	     * name and postcode). The value excludes the owner being created (which has not yet been saved), so
486	     * the household's size after this create is this count plus one. It is stored on the new owner.
487	     *
488	     * @param lastName the last name of the owner being created
489	     * @param postcode the postcode of the owner being created
490	     * @return the number of existing owners sharing this owner's household
491	     */
492	    private int countHouseholdMembers(String lastName, String postcode) {
493	        String householdId = Households.householdId(lastName, postcode);
494	        return (int) this.clinicService.findAllOwners().stream()
495	            .filter(existing -> householdId.equals(
496	                Households.householdId(existing.getLastName(), existing.getPostcode())))
497	            .count();
498	    }
499	
500	    /**
501	     * Computes the {@code membershipLevel} to store for the owner being created, applying the household
502	     * ceiling. The owner's natural level is first derived from their own fields (see
503	     * {@link org.springframework.samples.petclinic.util.Memberships#membershipLevel(String, Integer, Integer, java.time.LocalDate)}).
504	     * It is then capped so it cannot exceed one above the current maximum {@code membershipLevel} among
505	     * the owner's existing household members (the non-deleted owners sharing its {@code householdId}, see
506	     * {@link Households#householdId}). When the owner has no existing household member no cap applies and
507	     * the natural level is returned.
508	     *
509	     * @param owner the owner being created, with its level-affecting fields already populated
510	     * @return the (possibly capped) membership level to store on the owner
511	     */
512	    private int cappedMembershipLevel(Owner owner) {
513	        int naturalLevel = org.springframework.samples.petclinic.util.Memberships.membershipLevel(
514	            owner.getEmail(), owner.getNamesakeCount(), owner.getHouseholdSize(), owner.getRegistrationDate());
515	        String householdId = Households.householdId(owner.getLastName(), owner.getPostcode());
516	        java.util.OptionalInt maxMemberLevel = this.clinicService.findAllOwners().stream()
517	            .filter(this::isNotDeleted)
518	            .filter(existing -> householdId.equals(
519	                Households.householdId(existing.getLastName(), existing.getPostcode())))
520	            .mapToInt(this::effectiveMembershipLevel)
521	            .max();
522	        if (maxMemberLevel.isEmpty()) {
523	            return naturalLevel;
524	        }
525	        return Math.min(naturalLevel, maxMemberLevel.getAsInt() + 1);
526	    }
527	
528	    /**
529	     * Returns an existing owner's effective {@code membershipLevel}: the stored value when present (the
530	     * value assigned, and possibly capped, when that owner was created), otherwise the level derived
531	     * from its own fields for owners that predate the stored level (e.g. seed data).
532	     *
533	     * @param owner an existing owner
534	     * @return the owner's effective membership level
535	     */
536	    private int effectiveMembershipLevel(Owner owner) {
537	        if (owner.getMembershipLevel() != null) {
538	            return owner.getMembershipLevel();
539	        }
540	        return org.springframework.samples.petclinic.util.Memberships.membershipLevel(
541	            owner.getEmail(), owner.getNamesakeCount(), owner.getHouseholdSize(), owner.getRegistrationDate());
542	    }
543	
544	    /**
545	     * Finds the existing owner, if any, that the owner being created is a soft duplicate of: an owner
546	     * sharing this owner's {@code soundex(lastName)} and postcode (an exact match of the stored 4-digit
547	     * value) while carrying a <em>different</em> {@code identityKey}. A soft match is distinct from the
548	     * hard duplicate rejected earlier by {@link #rejectDuplicateIdentity} (which requires an identical
549	     * identity key): the owner is still created, but flagged. Because the telephone is part of the
550	     * identity key, two owners with the same last name and postcode but different telephones are a soft
551	     * match rather than a hard duplicate. When more than one existing owner matches, the earliest
552	     * (lowest id) is returned so the reference is deterministic. An owner with no postcode can never
553	     * soft-match.
554	     *
555	     * @param owner the owner being created, with its telephone and postcode already normalized/validated
556	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
557	     */
558	    private Integer findPossibleDuplicateOf(Owner owner) {
559	        String postcode = owner.getPostcode();
560	        if (postcode == null) {
561	            return null;
562	        }
563	        String soundex = Households.soundex(owner.getLastName());
564	        String identity = Households.identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
565	        return this.clinicService.findAllOwners().stream()
566	            .filter(this::isNotDeleted)
567	            .filter(existing -> soundex.equals(Households.soundex(existing.getLastName())))
568	            .filter(existing -> postcode.equals(existing.getPostcode()))
569	            .filter(existing -> !identity.equals(Households.identityKey(
570	                toE164OrNull(existing.getTelephone()), existing.getEmail(), existing.getLastName())))
571	            .map(Owner::getId)
572	            .filter(java.util.Objects::nonNull)
573	            .min(java.util.Comparator.naturalOrder())
574	            .orElse(null);
575	    }
576	
577	    /**
578	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
579	     * stripped. A leading '+' and its country code are kept as given; otherwise country code '+61' is
580	     * assumed and a single leading '0' is dropped from the national digits. The resulting number must
581	     * have 8 to 15 digits after the '+'. For example {@code "0412 345 678"} becomes
582	     * {@code "+61412345678"}. The E.164 value is stored and returned.
583	     * <p>
584	     * The national-number length (the digits after the country code) is additionally validated for
585	     * country codes with a fixed length: '+61' requires exactly 9 national digits and '+1' requires
586	     * exactly 10. Numbers of other country codes are only bound by the overall 8-to-15-digit limit.
587	     *
588	     * @param telephone the raw telephone as submitted
589	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
590	     * @throws InvalidTelephoneException (400 Bad Request) if the value cannot form a valid E.164 number
591	     *         or its national-number length is wrong for its country code
592	     */
593	    private String normalizeTelephone(String telephone) {
594	        String raw = telephone == null ? "" : telephone.trim();
595	        boolean hasCountryCode = raw.startsWith("+");
596	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
597	        if (hasCountryCode) {
598	            cleaned = cleaned.substring(1);
599	        }
600	        String digits;
601	        if (hasCountryCode) {
602	            digits = cleaned;
603	        } else {
604	            if (cleaned.startsWith("0")) {
605	                cleaned = cleaned.substring(1);
606	            }
607	            digits = "61" + cleaned;
608	        }
609	        if (!digits.matches("[0-9]{8,15}") || !hasValidNationalLength(digits)) {
610	            throw new InvalidTelephoneException(telephone);
611	        }
612	        return "+" + digits;
613	    }
614	
615	    /**
616	     * Checks the national-number length of an E.164 digit string against its country code for the
617	     * country codes whose national number has a fixed length: '+61' requires 9 national digits and
618	     * '+1' requires 10. Any other country code passes, leaving it bound only by the overall length.
619	     *
620	     * @param digits the E.164 digits (the country code followed by the national number, without '+')
621	     * @return {@code true} if the national-number length is acceptable for the country code
622	     */
623	    private boolean hasValidNationalLength(String digits) {
624	        if (digits.startsWith("61")) {
625	            return digits.length() - 2 == 9;
626	        }
627	        if (digits.startsWith("1")) {
628	            return digits.length() - 1 == 10;
629	        }
630	        return true;
631	    }
632	
633	    /**
634	     * Syntactic email pattern: a non-empty local part, an '@', a domain with at least one dot and a
635	     * multi-character top-level label. Deliberately lenient about the exact character set while still
636	     * rejecting values that are clearly not addresses (e.g. missing '@').
637	     */
638	    private static final java.util.regex.Pattern EMAIL_PATTERN =
639	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$");
640	
641	    /**
642	     * Domains of known disposable/throwaway email providers. An owner whose email domain is on this
643	     * blocklist is rejected with a 400 Bad Request. Compared case-insensitively against the
644	     * lower-cased email domain.
645	     */
646	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
647	        "mailinator.com", "tempmail.com", "guerrillamail.com");
648	
649	    /**
650	     * Normalizes an owner's email. Email is optional: a {@code null} or blank value is left as
651	     * {@code null} (no email). When present it must be a syntactically valid address; the value is
652	     * lower-cased before being stored and returned.
653	     *
654	     * @param email the raw email as submitted, may be {@code null}
655	     * @return the lower-cased email, or {@code null} when none was supplied
656	     * @throws InvalidEmailException (400 Bad Request) if a non-blank value is not a valid address
657	     */
658	    private String normalizeEmail(String email) {
659	        if (email == null || email.isBlank()) {
660	            return null;
661	        }
662	        String trimmed = email.trim();
663	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
664	            throw new InvalidEmailException(email);
665	        }
666	        String normalized = trimmed.toLowerCase(java.util.Locale.ROOT);
667	        String domain = normalized.substring(normalized.indexOf('@') + 1);
668	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
669	            throw new DisposableEmailException(email);
670	        }
671	        return normalized;
672	    }
673	
674	    /**
675	     * Fixed region-to-postcode-range table: a region's postcode must fall within its inclusive range
676	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city whose region is not listed here (see
677	     * {@link Localities#region}) accepts any 4-digit postcode.
678	     */
679	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
680	        "NSW", new int[] {2000, 2099},
681	        "VIC", new int[] {3000, 3099},
682	        "QLD", new int[] {4000, 4099});
683	
684	    /**
685	     * Validates an owner's postcode on create. The postcode is optional: a {@code null} or blank value
686	     * is left as {@code null} (no postcode) and accepted. When present it must be exactly 4 digits and,
687	     * for a city whose region is in the fixed {@link #REGION_POSTCODE_RANGES range table}, must fall
688	     * within that region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no
689	     * known region accepts any 4-digit postcode. The value is stored and returned exactly as supplied.
690	     *
691	     * @param city the owner's city, used to derive the region whose range constrains the postcode
692	     * @param postcode the raw postcode as submitted, may be {@code null}
693	     * @return the postcode when supplied, or {@code null} when none was supplied
694	     * @throws InvalidPostcodeException (400 Bad Request) if a supplied postcode is not 4 digits or is
695	     *         out of range for the city's region
696	     */
697	    private String validatePostcode(String city, String postcode) {
698	        if (postcode == null || postcode.isBlank()) {
699	            return null;
700	        }
701	        if (!postcode.matches("[0-9]{4}")) {
702	            throw new InvalidPostcodeException(postcode);
703	        }
704	        int[] range = REGION_POSTCODE_RANGES.get(Localities.region(city));
705	        if (range != null) {
706	            int value = Integer.parseInt(postcode);
707	            if (value < range[0] || value > range[1]) {
708	                throw new InvalidPostcodeException(postcode);
709	            }
710	        }
711	        return postcode;
712	    }
713	
714	    /**
715	     * Common street-type abbreviations expanded to their full word during address normalization.
716	     */
717	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS = java.util.Map.of(
718	        "ST", "STREET",
719	        "RD", "ROAD",
720	        "AVE", "AVENUE");
721	
722	    /**
723	     * Applies the owner's address on create from the structured fields when present, falling back to the
724	     * flat {@code address} for backward compatibility. An owner must supply an address in at least one
725	     * form: a non-blank {@code addressLine1} (the structured form, preferred) or a non-blank flat
726	     * {@code address}; when neither is present the create is rejected.
727	     * <p>
728	     * Whichever address fields are supplied are normalized (see {@link #normalizeAddress}). When the
729	     * structured form is used the normalized {@code addressLine1} and, when supplied, {@code addressLine2}
730	     * are stored on the owner and the composed {@code address} is the normalized {@code addressLine1} with
731	     * a single space and the normalized {@code addressLine2} appended when {@code addressLine2} is present.
732	     * When only the flat form is used the normalized flat value becomes the stored {@code address} and the
733	     * structured lines are left unset. The stored {@code address} is the value every later step reads.
734	     *
735	     * @param owner the owner being created
736	     * @param ownerFieldsDto the submitted owner fields carrying the raw address input
737	     * @throws InvalidAddressException (400 Bad Request) if no address is supplied in either form
738	     */
739	    private void applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
740	        String rawLine1 = ownerFieldsDto.getAddressLine1();
741	        String rawLine2 = ownerFieldsDto.getAddressLine2();
742	        String rawFlat = ownerFieldsDto.getAddress();
743	        boolean hasLine1 = rawLine1 != null && !rawLine1.isBlank();
744	        boolean hasFlat = rawFlat != null && !rawFlat.isBlank();
745	        if (!hasLine1 && !hasFlat) {
746	            throw new InvalidAddressException(rawLine1 != null ? rawLine1 : rawFlat);
747	        }
748	        if (hasLine1) {
749	            String line1 = normalizeAddress(rawLine1);
750	            String line2 = (rawLine2 != null && !rawLine2.isBlank()) ? normalizeAddress(rawLine2) : null;
751	            owner.setAddressLine1(line1);
752	            owner.setAddressLine2(line2);
753	            owner.setAddress(line2 != null ? line1 + " " + line2 : line1);
754	        } else {
755	            owner.setAddressLine1(null);
756	            owner.setAddressLine2(null);
757	            owner.setAddress(normalizeAddress(rawFlat));
758	        }
759	    }
760	
761	    /**
762	     * Normalizes an owner's address on create. Surrounding whitespace is trimmed and internal runs of
763	     * whitespace collapse to a single space, the value is upper-cased and common street-type
764	     * abbreviations are expanded to their full word ({@code ST} to {@code STREET}, {@code RD} to
765	     * {@code ROAD}, {@code AVE} to {@code AVENUE}). For example {@code "  12  main  st "} becomes
766	     * {@code "12 MAIN STREET"}. The normalized value is stored and returned, and is also the form used
767	     * for every address comparison (household duplicate detection and the shared household id).
768	     *
769	     * @param address the raw address as submitted
770	     * @return the normalized address
771	     * @throws InvalidAddressException (400 Bad Request) if the address is blank after normalization
772	     */
773	    private String normalizeAddress(String address) {
774	        String collapsed = (address == null ? "" : address).trim().replaceAll("\\s+", " ");
775	        if (collapsed.isEmpty()) {
776	            throw new InvalidAddressException(address);
777	        }
778	        String[] tokens = collapsed.toUpperCase(java.util.Locale.ROOT).split(" ");
779	        StringBuilder normalized = new StringBuilder(collapsed.length());
780	        for (int i = 0; i < tokens.length; i++) {
781	            if (i > 0) {
782	                normalized.append(' ');
783	            }
784	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
785	        }
786	        return normalized.toString();
787	    }
788	
789	    /**
790	     * Rejects creating an owner whose identity duplicates an existing owner's. All duplicate detection
791	     * is consolidated onto the single derived {@code identityKey} (see
792	     * {@link Households#identityKey(String, String, String)}): the SHA-256 hex over the normalized
793	     * telephone, the lower-cased email (a {@code null} email compared as an empty segment) and the
794	     * {@code soundex} of the last name. Two owners are duplicates when their identity keys are equal.
795	     * Existing telephones are re-normalized to E.164 before comparison, so equivalent values submitted
796	     * in different formats (e.g. national {@code "0412 345 678"} and international
797	     * {@code "+61 412 345 678"}) still match. The email-domain blocklist is applied first (during
798	     * email normalization), and soft-deleted owners are ignored.
799	     * <p>
800	     * Because the telephone is part of the key, two members of one household (same last name and
801	     * postcode) with different telephones have different identity keys and are both allowed; such a
802	     * near-match is instead surfaced as a soft duplicate (see {@link #findPossibleDuplicateOf}).
803	     *
804	     * @param owner the owner being created, with its telephone and email already normalized
805	     * @throws DuplicateIdentityException (409 Conflict) if another owner has the same identity key
806	     */
807	    private void rejectDuplicateIdentity(Owner owner) {
808	        String identity = Households.identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
809	        boolean duplicate = this.clinicService.findAllOwners().stream()
810	            .filter(this::isNotDeleted)
811	            .anyMatch(existing -> identity.equals(Households.identityKey(
812	                toE164OrNull(existing.getTelephone()), existing.getEmail(), existing.getLastName())));
813	        if (duplicate) {
814	            throw new DuplicateIdentityException(identity);
815	        }
816	    }
817	
818	    /**
819	     * Whether an existing owner is not soft-deleted. A soft-deleted owner (its {@code deleted} flag
820	     * set) is retained but ignored by the create endpoint's duplicate and identity checks, so a
821	     * normally-blocking duplicate is allowed when the only matching owner has been deleted.
822	     */
823	    private boolean isNotDeleted(Owner owner) {
824	        return !Boolean.TRUE.equals(owner.getDeleted());
825	    }
826	
827	    /**
828	     * Normalizes an existing owner's telephone to E.164 for duplicate comparison, returning
829	     * {@code null} instead of throwing when the stored value cannot form a valid E.164 number, or
830	     * when its national-number length does not match its country code.
831	     */
832	    private String toE164OrNull(String telephone) {
833	        try {
834	            return normalizeTelephone(telephone);
835	        } catch (InvalidTelephoneException e) {
836	            return null;
837	        }
838	    }
839	
840	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
841	    @Override
842	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
843	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
844	        if (currentOwner == null) {
845	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
846	        }
847	        currentOwner.setAddress(ownerFieldsDto.getAddress());
848	        currentOwner.setCity(ownerFieldsDto.getCity());
849	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
850	        currentOwner.setLastName(ownerFieldsDto.getLastName());
851	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
852	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
853	        this.clinicService.saveOwner(currentOwner);
854	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
855	    }
856	
857	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
858	    @Transactional
859	    @Override
860	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
861	        Owner owner = this.clinicService.findOwnerById(ownerId);
862	        if (owner == null) {
863	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
864	        }
865	        this.clinicService.deleteOwner(owner);
866	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
867	    }
868	
869	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
870	    @Override
871	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
872	        Owner owner = this.clinicService.findOwnerById(ownerId);
873	        if (owner == null) {
874	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
875	        }
876	        HttpHeaders headers = new HttpHeaders();
877	        Pet pet = petMapper.toPet(petFieldsDto);
878	        owner.setId(ownerId);
