887	
888	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
889	    @Override
890	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
891	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
892	        if (currentOwner != null) {
893	            Pet currentPet = this.clinicService.findPetById(petId);
894	            if (currentPet != null) {
